330	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
331	        OwnerPageDto ownerPageDto = new OwnerPageDto();
332	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
333	        ownerPageDto.setPage(ownerPage.getNumber());
334	        ownerPageDto.setSize(ownerPage.getSize());
335	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
336	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
337	        return ownerPageDto;
338	    }
339	}
